    /**
     * Given a number of case-sensitive strings, finds the largest string X, such that either X, or its inverse can be found as a substring of any of the given strings.
     * 
     * Example:
     * >>> findLargestSubstring(Arrays.asList("ABCD", "BCDFF", "BRCD"))
     * 2
     * >>> findLargestSubstring(Arrays.asList("rose", "orchid"))
     * 2
     */
    public int findLargestSubstring(List<String> strings)

canonical_solution:
{
    int maxLen = 0; // To keep track of the maximum length of substring found
    if (strings == null || strings.isEmpty()) {
        return maxLen;
    }

    String firstString = strings.get(0);

    // Iterate over all possible substrings of the first string
    for (int i = 0; i < firstString.length(); i++) {
        for (int j = i + 1; j <= firstString.length(); j++) {
            String substr = firstString.substring(i, j);
            String inverse = new StringBuilder(substr).reverse().toString();

            boolean allContains = true; // Flag to check if all strings contain the substring or its inverse

            // Check for each string in the list
            for (String str : strings) {
                if (!str.contains(substr) && !str.contains(inverse)) {
                    allContains = false;
                    break;
                }
            }

            // Update maxLen if a larger valid substring is found
            if (allContains) {
                maxLen = Math.max(maxLen, substr.length());
            }
        }
    }

    return maxLen;
}

