    for (int i = 0; i < words.length; i++) {
        words[i] = new StringBuilder(words[i]).reverse().toString();
    }

    // Join the reversed words back together into a single string
    return String.join(" ", words);
}

public static String reverseWords(String s) {
    // Split the input string into words
    String[] words = s.split(" ");

    // Reverse the characters in each word
    StringBuilder reversedWords = new StringBuilder();
    for (String word : words) {
        reversedWords.append(new StringBuilder(word).reverse());
        reversedWords.append(" ");
    }

    // Remove the trailing space and return the reversed string
    return reversedWords.substring(0, reversedWords.length() - 1);
}
